{{ config(materialized = 'ephemeral') }}

-- ZOOMINFO_DEV -> company_segment: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_company_segment as (
    select
        upper(trim(o.ZOOMINFO_ID)) as source_unique_id,
        o.EFFECTIVE_FROM as valid_from,
        o.EFFECTIVE_TO as valid_to
    from {{ source('company_segment_zoominfo_dev_source', 'company_dim') }} as o
    where nullif(upper(trim(o.ZOOMINFO_ID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ZOOMINFO_ID)) order by o.EFFECTIVE_FROM desc) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_company('ZOOMINFO_DEV') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        hub.company_core_skey as company_core_skey,
        null as ref_segment_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_SEGMENT_SKEY */,
        null as ref_service_line_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_SERVICE_LINE_SKEY */,
        o.valid_from::timestamp_ntz as valid_from,
        o.valid_to::timestamp_ntz as valid_to,
        null as source_segment_name /* TODO: no join path to SILVER_ZOOMINFO_COMPANY */,
        null as source_service_line_name,
        true as gdp_is_active,
        current_timestamp()::timestamp_ntz as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        o.EFFECTIVE_FROM as gdp_updated_ts,
        current_user() as gdp_updated_by
    from sp_company_segment as o
    cross join ref_source_system as r
    left join (
        select source_unique_id, company_core_skey
        from {{ ref('company_core') }}
        where gdp_is_active
        qualify row_number() over (partition by source_unique_id order by gdp_inserted_ts desc) = 1
    ) as hub
        on hub.source_unique_id = o.source_unique_id
)

select
    {{ this.schema }}.seq_company_segment_skey.nextval as company_segment_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    company_core_skey,
    ref_segment_skey,
    ref_service_line_skey,
    valid_from,
    valid_to,
    {{ m_company_segment_hkey() }} as company_segment_hkey,
    source_segment_name,
    source_service_line_name,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by
from base
